<template>
  <div class="question-page"><header class="page-top"><div><h1 class="page-title">题库选题</h1><p class="page-subtitle">高中数学 · 原创演示题库</p></div><div class="tools"><el-button :icon="Star" @click="savedOnly=!savedOnly">{{savedOnly?'全部题目':'我的收藏'}} {{savedIds.length}}</el-button><el-button type="primary" @click="$router.push('/papers')">进入组卷</el-button></div></header>
    <nav class="tabs" aria-label="选题方式"><button v-for="item in ['章节选题','知识点选题']" :key="item" :class="{active:mode===item}" @click="mode=item">{{item}}</button><router-link to="/paper-library">试卷选题</router-link><router-link to="/papers">智能组卷</router-link></nav>
    <div class="question-layout"><aside class="filters"><div class="filter-head"><strong>{{mode==='章节选题'?'教材章节':'知识点目录'}}</strong><el-button text size="small" @click="reset">重置</el-button></div><el-select v-model="book" aria-label="教材版本"><el-option label="全部版本" value=""/><el-option label="人教 A 版（2019）" value="人教A版（2019）"/><el-option label="北师大版" value="北师大版"/></el-select><div class="chapters"><button :class="{active:!chapterFilter}" @click="chapterFilter=''">全部章节 <small>{{list.length}}</small></button><button v-for="chapter in demoMeta.chapters" :key="chapter" :class="{active:chapterFilter===chapter}" @click="chapterFilter=chapter">{{chapter}}<small>{{list.filter(q=>q.chapter===chapter).length}}</small></button></div><label class="filter-label" for="chapter-search">目录内搜索</label><el-input id="chapter-search" v-model="treeKeyword" placeholder="章节名称" clearable/><div v-if="treeKeyword" class="tree-results"><button v-for="chapter in demoMeta.chapters.filter(c=>c.includes(treeKeyword))" :key="chapter" @click="chapterFilter=chapter;treeKeyword=''">{{chapter}}</button></div><label class="filter-label">题目场景</label><el-checkbox-group v-model="sceneFilter"><el-checkbox v-for="scene in demoMeta.scenes" :key="scene" :label="scene" :value="scene"/></el-checkbox-group></aside>
    <section class="results"><div class="search-row"><el-input v-model="keyword" :prefix-icon="Search" size="large" clearable placeholder="搜索题干、知识点或题源" aria-label="搜索题目"/></div><div class="filter-strip"><el-select v-model="typeFilter" aria-label="题型"><el-option label="全部题型" value=""/><el-option v-for="t in demoMeta.types" :key="t" :label="t" :value="t"/></el-select><el-select v-model="difficulty" aria-label="难度"><el-option label="全部难度" value=""/><el-option label="基础" :value="2"/><el-option label="中档" :value="3"/><el-option label="拔高" :value="4"/></el-select><el-select v-model="year" aria-label="年份"><el-option label="全部年份" value=""/><el-option v-for="y in [2026,2025,2024]" :key="y" :label="String(y)" :value="y"/></el-select><el-select v-model="region" aria-label="地区"><el-option label="全部地区" value=""/><el-option v-for="r in ['全国','北京','浙江']" :key="r" :label="r" :value="r"/></el-select><el-checkbox v-model="figuresOnly">带图题目</el-checkbox></div>
      <div class="result-head"><span>共 <b>{{filtered.length}}</b> 道题 <el-tag v-if="savedOnly" size="small">仅收藏</el-tag></span><div><el-select v-model="sort" aria-label="排序" size="small"><el-option label="综合排序" value="all"/><el-option label="年份由新到旧" value="new"/><el-option label="由易到难" value="difficulty"/></el-select><el-button size="small" :disabled="!pageItems.length" @click="addPage">本页加入试题篮</el-button></div></div>
      <article v-for="(q,i) in pageItems" :key="q.id" class="question"><div class="q-head"><div><el-tag size="small">{{q.type}}</el-tag><span>{{q.year}} · {{q.region}} · {{q.source}}</span></div><el-button :icon="savedIds.includes(q.id)?StarFilled:Star" circle text :aria-label="savedIds.includes(q.id)?'取消收藏':'收藏'" :class="{saved:savedIds.includes(q.id)}" @click="toggleSaved(q.id)"/></div><div class="stem-row"><span class="q-index">{{(page-1)*pageSize+i+1}}</span><QuestionContent :question="q"/></div><div class="q-foot"><div class="tags"><span v-for="tag in q.tags" :key="tag">{{tag}}</span><span>难度系数 {{q.coefficient}}</span></div><div class="actions"><el-button size="small" :type="hasQuestion(q.id)?'success':'primary'" plain @click="toggleBasket(q)">{{hasQuestion(q.id)?'已加入 · 移除':'加入试题篮'}}</el-button><el-button size="small" text @click="$router.push('/questions/'+q.id)">解析</el-button><el-button size="small" text @click="$router.push('/questions/'+q.id+'?feedback=1')">纠错</el-button></div></div></article>
      <el-empty v-if="!filtered.length" description="没有匹配题目"><el-button @click="reset">重置筛选</el-button></el-empty><div class="pagination"><span>每页 {{pageSize}} 题</span><el-pagination v-model:current-page="page" background layout="prev, pager, next" :pager-count="5" :total="filtered.length" :page-size="pageSize"/></div>
    </section></div>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Search, Star, StarFilled } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { cloneQuestions, demoMeta } from '../mock'
import QuestionContent from '../components/QuestionContent.vue'
import { useWorkspace } from '../composables/workspace'
const route=useRoute(), {basket,savedIds,addQuestions,removeQuestion,toggleSaved}=useWorkspace()
const list=cloneQuestions(),mode=ref('章节选题'),book=ref(''),chapterFilter=ref(String(route.query.chapter||'')),treeKeyword=ref(''),sceneFilter=ref([]),keyword=ref(''),typeFilter=ref(''),difficulty=ref(''),year=ref(''),region=ref(''),figuresOnly=ref(false),sort=ref('all'),savedOnly=ref(false),page=ref(1),pageSize=5
const filtered=computed(()=>list.filter(q=>(!keyword.value||[q.stem,q.source,...q.tags].join(' ').toLowerCase().includes(keyword.value.trim().toLowerCase()))&&(!book.value||q.book===book.value)&&(!chapterFilter.value||q.chapter===chapterFilter.value)&&(!sceneFilter.value.length||sceneFilter.value.includes(q.scene))&&(!typeFilter.value||q.type===typeFilter.value)&&(!difficulty.value||q.difficulty===difficulty.value)&&(!year.value||q.year===year.value)&&(!region.value||q.region===region.value)&&(!figuresOnly.value||q.figureUrl)&&(!savedOnly.value||savedIds.value.includes(q.id))).sort((a,b)=>sort.value==='new'?b.year-a.year:sort.value==='difficulty'?a.difficulty-b.difficulty:0))
const pageItems=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize))
watch([book,chapterFilter,sceneFilter,keyword,typeFilter,difficulty,year,region,figuresOnly,sort,savedOnly],()=>page.value=1,{deep:true})
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/pageSize)))})
function reset(){book.value='';chapterFilter.value='';sceneFilter.value=[];keyword.value='';typeFilter.value='';difficulty.value='';year.value='';region.value='';figuresOnly.value=false;savedOnly.value=false;treeKeyword.value=''}
function hasQuestion(id){return basket.value.some(q=>q.id===id)}
function toggleBasket(q){if(hasQuestion(q.id))removeQuestion(q.id);else if(addQuestions([q]))ElMessage.success('已加入试题篮')}
function addPage(){if(addQuestions(pageItems.value))ElMessage.success('本页题目已加入，重复题目已忽略')}
</script>
<style scoped>
.question-page{max-width:1400px;margin:auto}.page-top,.q-head,.q-foot,.result-head,.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px}.page-top{margin-bottom:22px}.tools{display:flex;gap:8px}.tools .el-button+.el-button{margin-left:0}.tabs{display:flex;gap:28px;overflow:auto;border-bottom:1px solid var(--line);margin-bottom:22px}.tabs button,.tabs a{border:0;background:none;white-space:nowrap;padding:14px 0;color:#61758a;cursor:pointer;text-decoration:none;font-size:13px}.tabs .active{color:var(--primary);border-bottom:2px solid var(--primary);font-weight:600}.question-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px}.filters{border-right:1px solid var(--line);padding-right:20px}.filter-head{display:flex;justify-content:space-between;align-items:center;font-size:13px;margin-bottom:12px}.filter-label{display:block;margin:22px 0 12px;color:var(--text-2);font-size:12px}.chapters{margin-top:15px}.chapters button,.tree-results button{display:flex;gap:8px;justify-content:space-between;width:100%;text-align:left;border:0;background:none;padding:11px 8px;color:#5f7083;cursor:pointer;font-size:12px;line-height:1.5}.chapters button.active{color:var(--primary);background:#eaf2fc}.chapters small{white-space:nowrap;color:#8a9aa8}.filters .el-checkbox{display:flex;margin:0}.results{min-width:0}.filter-strip{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid var(--line)}.filter-strip .el-select{width:118px}.result-head{padding:17px 0;color:#728294;font-size:12px}.result-head>div{display:flex;gap:8px;align-items:center}.result-head .el-select{width:140px}.question{background:white;border:1px solid var(--line);border-radius:6px;padding:18px;margin-bottom:14px}.q-head>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.q-head span:not(.el-tag){font-size:11px;color:#7d8d9d}.saved{color:#b48225}.stem-row{display:flex;gap:12px;margin:15px 0 18px}.stem-row>.question-content{flex:1}.q-index{font-size:12px;color:#728294;padding-top:4px;width:20px;flex:none}.q-foot{border-top:1px solid var(--line);padding-top:13px;flex-wrap:wrap}.tags{display:flex;gap:8px;flex-wrap:wrap}.tags span{background:#f2f5f7;color:#6b7c8e;font-size:11px;padding:4px 7px;border-radius:3px}.actions{display:flex;align-items:center}.actions .el-button+.el-button{margin-left:5px}.pagination{padding:14px 0;color:#788b9b;font-size:12px}@media(max-width:900px){.question-layout{grid-template-columns:1fr}.filters{border-right:0;border-bottom:1px solid var(--line);padding:0 0 14px}.filters>.el-select{width:230px}.chapters{display:flex;overflow:auto}.chapters button{width:auto;white-space:nowrap;flex:none}.filters .el-checkbox-group{display:flex;gap:15px;flex-wrap:wrap}.filter-label[for=chapter-search],#chapter-search,.tree-results{display:none}}@media(max-width:600px){.page-top,.result-head{align-items:flex-start;flex-direction:column}.tools{margin-top:5px}.filter-strip .el-select{width:calc(50% - 5px)}.question{padding:14px}.q-head>div{gap:7px}.tabs{gap:22px}.pagination>span{display:none}.pagination{justify-content:center}.result-head>div{width:100%}.result-head .el-select{flex:1}.q-foot{gap:12px}}
</style>
